const error = $input.first().json;
const workflowName = error.workflow?.name || 'Unknown Workflow';
const nodeName = error.execution?.lastNodeExecuted || 'Unknown Node';
const errorMessage = error.error?.message || 'Unknown error';
const errorId = `ERR-${Date.now()}`;

// Determine severity
let severity = 'Medium';
if (errorMessage.toLowerCase().includes('connection') || errorMessage.toLowerCase().includes('timeout')) {
  severity = 'High';
}
if (workflowName.toLowerCase().includes('sahni') || workflowName.toLowerCase().includes('client')) {
  severity = 'Critical'; // Client-facing workflows are always critical
}

// Build WhatsApp alert
const alert = `🔴 *WORKFLOW ERROR*\n`
  + `*Workflow:* ${workflowName}\n`
  + `*Node:* ${nodeName}\n`
  + `*Error:* ${errorMessage.substring(0, 100)}\n`
  + `*Severity:* ${severity}\n`
  + `*Time:* ${new Date().toLocaleTimeString('en-IN')}\n`
  + `*ID:* ${errorId}\n\n`
  + `_Check Error Log in Agency OS sheet._`;

return {
  json: {
    errorId,
    workflowName,
    nodeName,
    errorMessage,
    severity,
    alert,
    timestamp: new Date().toISOString()
  }
};
